<template>
<section class="ventas"><header class="encabezado"><div><h1>Ventas por Stand</h1><p>Registra ventas únicamente sobre existencias recibidas y disponibles.</p></div></header>
<div v-if="error" class="alerta">{{error}}</div><div v-if="exito" class="correcto">{{exito}}</div>
<div class="panel"><h2>Nueva venta</h2><label>Stand asignado</label><select v-model="stand" @change="cargarStock"><option value="">Seleccione un stand</option><option v-for="s in stands" :key="s.id_ubicacion" :value="s.id_ubicacion">{{s.evento?.nombre || 'Evento'}} · {{s.nombre}}</option></select>
<div v-if="stand"><div class="cabecera-lineas"><h3>Productos disponibles</h3><button class="btn" @click="cargarStock">Actualizar existencias</button></div>
<div class="tabla"><table><thead><tr><th>Producto / presentación</th><th>Lote</th><th>Disponible</th><th>Precio (Bs)</th><th>Cantidad a vender</th></tr></thead><tbody>
<tr v-for="i in stock" :key="i.id_lote"><td>{{i.lote?.presentacion?.producto?.nombre || i.lote?.presentacion?.nombre_presentacion || 'Producto'}} · {{i.lote?.presentacion?.nombre_presentacion}}</td><td>{{i.lote?.codigo_lote}}</td><td>{{i.stock_actual}}</td><td>{{moneda(i.lote?.presentacion?.precio_unitario)}}</td><td><input type="number" min="0" :max="i.stock_actual" step="1" v-model.number="cantidades[i.id_lote]" /></td></tr>
<tr v-if="!stock.length"><td colspan="5">No hay existencias disponibles en este stand.</td></tr></tbody></table></div>
<label>Observación (opcional)</label><textarea v-model="observacion" maxlength="1000" placeholder="Detalle de la venta"></textarea>
<div class="pie"><strong>Total estimado: Bs {{moneda(total)}}</strong><button class="btn principal" :disabled="guardando || !lineas.length" @click="registrar">{{guardando?'Registrando...':'Confirmar venta'}}</button></div></div></div>
<div class="panel"><div class="cabecera-lineas"><h2>Historial de ventas</h2><button class="btn" @click="cargarVentas">Actualizar</button></div><div class="tabla"><table><thead><tr><th>N.º</th><th>Fecha</th><th>Stand</th><th>Usuario</th><th>Estado</th><th>Total (Bs)</th></tr></thead><tbody><tr v-for="v in ventas" :key="v.id_venta"><td>#{{v.id_venta}}</td><td>{{new Date(v.fecha_venta).toLocaleString('es-BO')}}</td><td>{{v.ubicacion?.nombre}}</td><td>{{v.usuario?.name}}</td><td>{{v.estado}}</td><td>{{moneda(v.total)}}</td></tr><tr v-if="!ventas.length"><td colspan="6">Sin ventas registradas.</td></tr></tbody></table></div></div>
</section>
</template>
<script>
import api from '../../services/api';
export default {data(){return {stands:[],stand:'',stock:[],cantidades:{},observacion:'',ventas:[],error:'',exito:'',guardando:false}},computed:{lineas(){return this.stock.filter(i=>Number(this.cantidades[i.id_lote])>0).map(i=>({id_lote:i.id_lote,cantidad:Number(this.cantidades[i.id_lote])}))},total(){return this.stock.reduce((s,i)=>s+(Number(this.cantidades[i.id_lote])||0)*Number(i.lote?.presentacion?.precio_unitario||0),0)}},async mounted(){try{const {data}=await api.get('/api/ventas-stand/stands');this.stands=data;await this.cargarVentas()}catch(e){this.error=e.response?.data?.message||'No se pudieron cargar los stands.'}},methods:{moneda(v){return Number(v||0).toFixed(2)},async cargarStock(){this.error='';this.stock=[];this.cantidades={};if(!this.stand)return;try{const {data}=await api.get('/api/ventas-stand/existencias',{params:{id_ubicacion:this.stand}});this.stock=data}catch(e){this.error=e.response?.data?.message||'No se pudieron consultar existencias.'}},async cargarVentas(){try{const {data}=await api.get('/api/ventas-stand',{params:this.stand?{id_ubicacion:this.stand}:{}});this.ventas=data.data||[]}catch(e){this.error=e.response?.data?.message||'No se pudo cargar el historial.'}},async registrar(){this.error='';this.exito='';if(this.lineas.some(x=>!Number.isInteger(x.cantidad)||x.cantidad<1)){this.error='Ingrese cantidades enteras mayores a cero.';return}if(this.lineas.some(x=>x.cantidad>this.stock.find(i=>i.id_lote===x.id_lote)?.stock_actual)){this.error='Una cantidad supera el stock disponible.';return}if(!confirm(`¿Confirmar venta por Bs ${this.moneda(this.total)}?`))return;this.guardando=true;try{const {data}=await api.post('/api/ventas-stand',{id_ubicacion:this.stand,observacion:this.observacion||null,detalles:this.lineas});this.exito=`Venta #${data.venta.id_venta} confirmada.`;this.observacion='';await this.cargarStock();await this.cargarVentas()}catch(e){this.error=e.response?.data?.message||'No se pudo registrar la venta.'}finally{this.guardando=false}}}}
</script>
<style scoped>
.ventas{max-width:1450px;margin:auto;padding:24px;color:#0c3025}.encabezado h1{font-size:30px;margin:0}.encabezado p{color:#60776a}.panel{background:#fff;border:1px solid #dce8df;border-radius:16px;padding:24px;margin:20px 0;box-shadow:0 6px 24px #103a2d0b}h2{font-size:20px;margin:0 0 18px}h3{font-size:16px}label{display:block;font-weight:700;margin:12px 0 7px}select,textarea,input{border:1px solid #cadcd0;border-radius:8px;padding:10px;font:inherit}select,textarea{width:100%}textarea{min-height:72px}.tabla{overflow-x:auto;margin-top:15px}table{width:100%;border-collapse:collapse}th{background:#0c3025;color:white;text-align:left}th,td{padding:12px;border-bottom:1px solid #e2ebe5}input{max-width:115px}.cabecera-lineas,.pie{display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap}.pie{margin-top:20px}.btn{border:1px solid #c8d9ce;background:white;color:#124734;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}.principal{background:#f47b20;border-color:#f47b20;color:white}.btn:disabled{opacity:.5;cursor:not-allowed}.alerta,.correcto{padding:12px;border-radius:8px;margin:12px 0}.alerta{background:#ffeded;color:#a22}.correcto{background:#e9f6ee;color:#175b3b}@media(max-width:700px){.ventas{padding:12px}.panel{padding:14px}}
</style>
